public class WhatsAppSimpleOrchestratorTests
{
 [Fact]public async Task ContextCatalog_ContainsOnlyBranchProductsAndCurrentFields(){await using var f=await Fixture.Create("Dame un ranchero familiar");AiChatRequest? captured=null;f.Provider.Setup(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>())).Callback<AiChatRequest,CancellationToken>((r,_)=>captured=r).ReturnsAsync(new AiChatResponse("Claro",[],"model","stop",1,1));await f.Orchestrator.ProcessIncomingMessageAsync(1,1);var context=captured!.Messages[1].Content!;Assert.Contains("Ranchero Familiar",context);Assert.Contains("73000",context);Assert.Contains("servesPeopleMin",context);Assert.Contains("available",context);Assert.DoesNotContain("Producto otra sucursal",context);Assert.Equal(4,captured.Tools.Count);}

 [Fact]public async Task IdentifiedCustomer_ContextContainsNameAndOnlySavedAddressesFromThatCustomer(){await using var f=await Fixture.Create("Hola");var neighborhood=new Neighborhood{Id=1,BranchId=1,Name="Laureles",DeliveryFee=6000};var customer=new Customer{Id=10,BranchId=1,Name="María",Phone1="300"};var otherCustomer=new Customer{Id=11,BranchId=1,Name="Otro",Phone1="301"};f.Db.AddRange(neighborhood,customer,otherCustomer,new Address{Id=20,CustomerId=10,NeighborhoodId=1,AddressText="Calle 10 # 20-30",AdditionalInfo="Apto 4",IsPrimary=true},new Address{Id=21,CustomerId=11,NeighborhoodId=1,AddressText="Dirección ajena"});(await f.Db.WhatsAppConversations.FindAsync(1))!.CustomerId=10;await f.Db.SaveChangesAsync();AiChatRequest? captured=null;f.Provider.Setup(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>())).Callback<AiChatRequest,CancellationToken>((r,_)=>captured=r).ReturnsAsync(new AiChatResponse("Hola María",[],"model","stop",1,1));await f.Orchestrator.ProcessIncomingMessageAsync(1,1);using var context=JsonDocument.Parse(captured!.Messages[1].Content!);var root=context.RootElement;Assert.Equal("María",root.GetProperty("customerName").GetString());Assert.True(root.GetProperty("isFirstAssistantReply").GetBoolean());var address=Assert.Single(root.GetProperty("savedAddresses").EnumerateArray());Assert.Equal("Calle 10 # 20-30",address.GetProperty("address").GetString());Assert.Equal("Laureles",address.GetProperty("neighborhood").GetString());Assert.True(address.GetProperty("isPrimary").GetBoolean());}

 [Fact]public async Task ClearMatch_ExecutesOnlyRancheroAndPersistsCart(){await using var f=await Fixture.Create("Dame un ranchero familiar");using var args=JsonDocument.Parse("""{"action":"add_product","productId":1,"quantity":1}""");f.Provider.SetupSequence(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>())).ReturnsAsync(new AiChatResponse(null,[new("c1","apply_order_action",args.RootElement.Clone())],"model","tool_calls",1,1)).ReturnsAsync(new AiChatResponse("Listo, agregué un Ranchero Familiar. ¿Deseas algo más?",[],"model","stop",1,1));var result=await f.Orchestrator.ProcessIncomingMessageAsync(1,1);Assert.Equal(2,result.ModelCalls);Assert.Equal(1,result.ToolsExecuted);Assert.Equal(1,(await f.State.LoadAsync(1)).Items.Single().ProductId);}

 [Fact]public async Task AmbiguousRequest_DoesNotModifyCart(){await using var f=await Fixture.Create("Dame un familiar");f.Provider.Setup(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>())).ReturnsAsync(new AiChatResponse("¿Cuál familiar prefieres: Ranchero, Paisa o Carbonara?",[],"model","stop",1,1));await f.Orchestrator.ProcessIncomingMessageAsync(1,1);Assert.Empty((await f.State.LoadAsync(1)).Items);f.Tools.Verify(x=>x.ExecuteAsync(It.IsAny<string>(),It.IsAny<AgentToolExecutionContext>(),It.IsAny<JsonElement>(),It.IsAny<CancellationToken>()),Times.Never);}

 [Theory][InlineData("El primero")][InlineData("Dije ranchero")]
 public async Task FollowUpReferences_ReceiveHistoryAndCanSelectRanchero(string text){await using var f=await Fixture.Create(text,withHistory:true);using var args=JsonDocument.Parse("""{"action":"add_product","productId":1,"quantity":1}""");var calls=0;f.Provider.Setup(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>())).Callback<AiChatRequest,CancellationToken>((request,_)=>{if(calls==0)Assert.Contains(request.Messages,x=>x.Role=="assistant"&&x.Content!.Contains("Ranchero"));}).ReturnsAsync(()=>++calls==1?new AiChatResponse(null,[new("c1","apply_order_action",args.RootElement.Clone())],"model","tool_calls",1,1):new AiChatResponse("Listo",[],"model","stop",1,1));await f.Orchestrator.ProcessIncomingMessageAsync(1,1);Assert.Equal(1,(await f.State.LoadAsync(1)).Items.Single().ProductId);}

 [Fact]public async Task Http400_IsNotRetried(){await using var f=await Fixture.Create("Hola",retries:2);f.Provider.Setup(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>())).ReturnsAsync(new AiChatResponse(null,[],"model",null,null,null,false,"bad request",400));await f.Orchestrator.ProcessIncomingMessageAsync(1,1);f.Provider.Verify(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>()),Times.Once);}

 [Fact]public async Task Http429_IsRetried(){await using var f=await Fixture.Create("Hola",retries:2);f.Provider.SetupSequence(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>())).ReturnsAsync(new AiChatResponse(null,[],"model",null,null,null,true,"rate limit",429)).ReturnsAsync(new AiChatResponse("Listo",[],"model","stop",1,1));await f.Orchestrator.ProcessIncomingMessageAsync(1,1);f.Provider.Verify(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>()),Times.Exactly(2));}

 [Fact]public async Task ProviderTimeoutResponse_IsRetried(){await using var f=await Fixture.Create("Hola",retries:2);f.Provider.SetupSequence(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>())).ReturnsAsync(new AiChatResponse(null,[],"model",null,null,null,true,"request timeout")).ReturnsAsync(new AiChatResponse("Listo",[],"model","stop",1,1));await f.Orchestrator.ProcessIncomingMessageAsync(1,1);f.Provider.Verify(x=>x.GenerateAsync(It.IsAny<AiChatRequest>(),It.IsAny<CancellationToken>()),Times.Exactly(2));}

 private sealed class Fixture:IAsyncDisposable
 {
  public ApplicationDbContext Db=null!;public Mock<IAiChatProvider> Provider=new();public Mock<IAgentToolExecutor> Tools=new();public WhatsAppSimpleOrderStateService State=null!;public IWhatsAppAiOrchestrator Orchestrator=null!;
  public static async Task<Fixture> Create(string text,bool withHistory=false,int retries=0){var f=new Fixture();f.Db=new(new DbContextOptionsBuilder<ApplicationDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);var b1=new Branch{Id=1,Name="Centro"};var b2=new Branch{Id=2,Name="Norte"};var c1=new ProductCategory{Id=1,BranchId=1,Name="Arroces"};var c2=new ProductCategory{Id=2,BranchId=2,Name="Arroces"};f.Db.AddRange(b1,b2,c1,c2,new Product{Id=1,CategoryId=1,Name="Ranchero Familiar",Price=73000,Stock=5,Active=true,ServesPeopleMin=3,ServesPeopleMax=4},new Product{Id=2,CategoryId=2,Name="Producto otra sucursal",Price=1,Active=true},new WhatsAppConversation{Id=1,BranchId=1,PhoneNumber="300",AttentionMode=WhatsAppAttentionMode.Ai},new BranchAiSetting{Id=1,BranchId=1,Provider="openai",Model="model",IsActive=true,IsVerified=true,MaxContextMessages=20});if(withHistory)f.Db.WhatsAppMessages.Add(new(){Id=-1,ConversationId=1,Direction=WhatsAppMessageDirection.Outbound,Type=WhatsAppMessageType.Text,TextBody="Ranchero, Paisa o Carbonara",Status=WhatsAppMessageStatus.Sent,Timestamp=DateTime.UtcNow.AddSeconds(-1)});f.Db.WhatsAppMessages.Add(new(){Id=1,ConversationId=1,Direction=WhatsAppMessageDirection.Inbound,Type=WhatsAppMessageType.Text,TextBody=text,Status=WhatsAppMessageStatus.Received,Timestamp=DateTime.UtcNow,AiProcessingStatus=WhatsAppAiProcessingStatus.Pending});await f.Db.SaveChangesAsync();var clock=Mock.Of<IClock>(x=>x.UtcNow==DateTime.UtcNow);f.State=new(f.Db,clock);var action=new ApplyOrderActionAgentTool(f.State,f.Db);f.Tools.SetupGet(x=>x.Definitions).Returns(Definitions());f.Tools.Setup(x=>x.ExecuteAsync("apply_order_action",It.IsAny<AgentToolExecutionContext>(),It.IsAny<JsonElement>(),It.IsAny<CancellationToken>())).Returns<string,AgentToolExecutionContext,JsonElement,CancellationToken>((_,c,a,ct)=>action.ExecuteAsync(c,a,ct));f.Provider.SetupGet(x=>x.ProviderName).Returns("openai");var resolver=new Mock<IAiChatProviderResolver>();resolver.Setup(x=>x.Resolve("openai")).Returns(f.Provider.Object);var apiKeys=Mock.Of<IAiApiKeyProvider>(x=>x.GetApiKey("openai")=="environment-key"&&x.GetEnvironmentVariableName("openai")=="OPENAI_API_KEY");var sender=new Mock<IWhatsAppAutomaticMessageSender>();sender.Setup(x=>x.SendTextAsync(It.IsAny<int>(),It.IsAny<int>(),It.IsAny<string>(),It.IsAny<string>(),It.IsAny<CancellationToken>())).ReturnsAsync(new WhatsAppAutomaticSendResult(true,false,"wamid",null));sender.Setup(x=>x.SendTransferTextAsync(It.IsAny<int>(),It.IsAny<int>(),It.IsAny<string>(),It.IsAny<string>(),It.IsAny<CancellationToken>())).ReturnsAsync(new WhatsAppAutomaticSendResult(true,false,"wamid",null));var prompt=Mock.Of<IWhatsAppSystemPromptBuilder>(x=>x.Build(1,It.IsAny<CancellationToken>())==Task.FromResult("prompt"));f.Orchestrator=new WhatsAppAiOrchestrator(f.Db,new Claimer(f.Db),resolver.Object,apiKeys,f.Tools.Object,sender.Object,Mock.Of<IWhatsAppNotificationService>(),prompt,f.State,new WhatsAppAttentionService(),clock,Options.Create(new WhatsAppAiOrchestratorOptions{MaxModelCallsPerMessage=2,MaxToolsPerCall=1,MaxTotalToolCalls=1,TransientRetryCount=retries,TotalTimeoutSeconds=10}),NullLogger<WhatsAppAiOrchestrator>.Instance);return f;}
  private static IReadOnlyList<AiToolDefinition> Definitions(){using var empty=JsonDocument.Parse("""{"type":"object","properties":{},"additionalProperties":false}""");return new[]{"apply_order_action","send_menu","send_product_details","request_human_assistance"}.Select(x=>new AiToolDefinition(x,x,empty.RootElement.Clone())).ToList();}
  public ValueTask DisposeAsync()=>Db.DisposeAsync();
 }
 private sealed class Claimer(ApplicationDbContext db):IWhatsAppAiMessageClaimer{public async Task<bool> TryClaimAsync(int c,int m,CancellationToken ct){var x=await db.WhatsAppMessages.FindAsync([m],ct);if(x?.AiProcessingStatus!=WhatsAppAiProcessingStatus.Pending)return false;x.AiProcessingStatus=WhatsAppAiProcessingStatus.Processing;x.AiProcessingAttempts++;await db.SaveChangesAsync(ct);return true;}public async Task<bool> TryCompleteAsync(int c,int m,DateTime at,CancellationToken ct){var x=await db.WhatsAppMessages.FindAsync([m],ct);if(x is null)return false;x.AiProcessingStatus=WhatsAppAiProcessingStatus.Completed;x.AiProcessedAt=at;await db.SaveChangesAsync(ct);return true;}}
}
